-- Revisión 17:47 del 24-11 (b): fechas de U2 en Baltimore y Arlington duplicadas (solo metadatos públicos de Ticketmaster)
SELECT s.source_id, s.local_date, s.first_seen_at, json_extract(s.snapshot_json, '$.name') AS evento, json_extract(s.snapshot_json, '$.venue.tmId') AS recinto, substr(json_extract(s.snapshot_json, '$.url'), 1, 120) AS url, json_extract(j.value, '$.kind') AS tipo, json_extract(j.value, '$.label') AS venta, json_extract(j.value, '$.startsAt') AS sale FROM show s JOIN artist a ON a.id = s.artist_id, json_each(s.snapshot_json, '$.sales') j WHERE a.name = 'U2' AND s.local_date IN ('2027-08-20', '2027-09-27');
